private void injectElement(ReduceFnTester<Integer, ?, IntervalWindow> tester, int element) throws Exception {
    doNothing().when(mockTriggerStateMachine).onElement(anyElementContext());
    tester.injectElements(TimestampedValue.of(element, new Instant(element)));
}

private void injectElements(ReduceFnTester<Integer, ?, IntervalWindow> tester, Iterable<Integer> values) throws Exception {
    doNothing().when(mockTriggerStateMachine).onElement(anyElementContext());
    List<TimestampedValue<Integer>> timestampedValues = new ArrayList<>();
    for (int value : values) {
        timestampedValues.add(TimestampedValue.of(value, new Instant(value)));
    }
    tester.injectElements(timestampedValues);
}

@Test
public void testOnElementBufferingDiscarding() throws Exception {
    // Test basic execution of a trigger using a non-combining window set and discarding mode.
    MetricsContainerImpl container = new MetricsContainerImpl("any");
    MetricsEnvironment.setCurrentContainer(container);
    ReduceFnTester<Integer, Iterable<Integer>, IntervalWindow> tester = ReduceFnTester.nonCombining(FixedWindows.of(Duration.millis(10)), mockTriggerStateMachine, AccumulationMode.DISCARDING_FIRED_PANES, Duration.millis(100), ClosingBehavior.FIRE_IF_NON_EMPTY);
    // Pane of {1, 2}
    injectElement(tester, 1);
