            for (WindowedValue<?> val : committed.getElements()) {
                outputs.add(val);
            }
        }
    }
    assertThat(outputs, containsInAnyOrder(gw(1L), gw(2L), gw(4L), gw(8L), gw(9L), gw(7L), gw(6L), gw(5L), gw(3L), gw(0L)));
}

