/**
 * When a callAfterWindowCloses with the specified view's producing transform, window, and
 * windowing strategy is invoked, start a thread that will invoke the callback after the returned
 * {@link CountDownLatch} is counted down once.
 */
private CountDownLatch invokeLatchedCallback(PCollectionView<?> view, BoundedWindow window, final CountDownLatch onComplete) {
    final CountDownLatch runLatch = new CountDownLatch(1);
    doAnswer(invocation -> {
        Object callback = invocation.getArguments()[3];
        final Runnable callbackRunnable = (Runnable) callback;
        ListenableFuture<?> result = MoreExecutors.listeningDecorator(Executors.newSingleThreadExecutor()).submit(() -> {
            try {
                if (!runLatch.await(1500L, TimeUnit.MILLISECONDS)) {
                    fail("Run latch didn't count down within timeout");
                }
                callbackRunnable.run();
                onComplete.countDown();
            } catch (InterruptedException e) {
                throw new AssertionError("Unexpectedly interrupted while waiting for latch ", e);
            }
        });
        return null;
    }).when(context).scheduleAfterOutputWouldBeProduced(Mockito.eq(view), Mockito.eq(window), Mockito.eq(view.getWindowingStrategyInternal()), Mockito.any(Runnable.class));
    return runLatch;
}

