@Test
public void testCreatingAndProcessingBeamFnDataReadRunner() throws Exception {
    String bundleId = "57";
    List<WindowedValue<String>> outputValues = new ArrayList<>();
    ListMultimap<String, FnDataReceiver<WindowedValue<?>>> consumers = ArrayListMultimap.create();
    String localOutputId = "outputPC";
    consumers.put(localOutputId, (FnDataReceiver) (FnDataReceiver<WindowedValue<String>>) outputValues::add);
    List<ThrowingRunnable> startFunctions = new ArrayList<>();
    List<ThrowingRunnable> finishFunctions = new ArrayList<>();
    RunnerApi.PTransform pTransform = RemoteGrpcPortRead.readFromPort(PORT_SPEC, localOutputId).toPTransform();
    new BeamFnDataReadRunner.Factory<String>().createRunnerForPTransform(PipelineOptionsFactory.create(), mockBeamFnDataClient, null, /* beamFnStateClient */
    "pTransformId", pTransform, Suppliers.ofInstance(bundleId)::get, ImmutableMap.of(localOutputId, RunnerApi.PCollection.newBuilder().setCoderId(ELEMENT_CODER_SPEC_ID).build()), COMPONENTS.getCodersMap(), COMPONENTS.getWindowingStrategiesMap(), consumers, startFunctions::add, finishFunctions::add, null);
    verifyZeroInteractions(mockBeamFnDataClient);
    InboundDataClient completionFuture = CompletableFutureInboundDataClient.create();
    when(mockBeamFnDataClient.receive(any(), any(), any(), any())).thenReturn(completionFuture);
    Iterables.getOnlyElement(startFunctions).run();
    verify(mockBeamFnDataClient).receive(eq(PORT_SPEC.getApiServiceDescriptor()), eq(LogicalEndpoint.of(bundleId, BeamFnApi.Target.newBuilder().setPrimitiveTransformReference("pTransformId").setName(Iterables.getOnlyElement(pTransform.getOutputsMap().keySet())).build())), eq(CODER), consumerCaptor.capture());
    consumerCaptor.getValue().accept(valueInGlobalWindow("TestValue"));
    assertThat(outputValues, contains(valueInGlobalWindow("TestValue")));
    outputValues.clear();
    assertThat(consumers.keySet(), containsInAnyOrder(localOutputId));
