@Test
public void shouldCheckpointReadRecords() throws TransientKinesisException, KinesisShardClosedException {
    when(firstIterator.readNextBatch()).thenReturn(ImmutableList.of(a, b)).thenReturn(Collections.emptyList());
    when(secondIterator.readNextBatch()).thenReturn(singletonList(c)).thenReturn(singletonList(d)).thenReturn(Collections.emptyList());
    shardReadersPool.start();
    int recordsFound = 0;
    while (recordsFound < 4) {
        CustomOptional<KinesisRecord> nextRecord = shardReadersPool.nextRecord();
        if (nextRecord.isPresent()) {
            recordsFound++;
            KinesisRecord kinesisRecord = nextRecord.get();
            if ("shard1".equals(kinesisRecord.getShardId())) {
                verify(firstIterator).ackRecord(kinesisRecord);
            } else {
                verify(secondIterator).ackRecord(kinesisRecord);
            }
        }
    }
}

